// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1e18);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        uint256 beforeDepositorBal = depositor.balance;
        uint256 beforeContractBal = address(c).balance;

        vm.prank(depositor);
        bool ok1;
        try c.withdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        assertTrue(ok1);

        uint256 afterDepositorBal = depositor.balance;
        uint256 afterContractBal = address(c).balance;

        assertTrue(afterContractBal + amount == beforeContractBal);

        vm.prank(depositor);
        bool ok2;
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assertTrue(ok2);

        uint256 finalContractBal = address(c).balance;

        assertTrue(finalContractBal == afterContractBal);
    }
}
